        Assertions.assertThatThrownBy(() -> consumer.poll()).isInstanceOf(MessagingException.class).message().matches(actualMessage -> Stream.of("LOGIN failed. Invalid login/password for user id", "Authentication failed: com.icegreen.greenmail.user.UserException: Invalid password").anyMatch(expectedSubstring -> actualMessage.contains(expectedSubstring)));
        // poll a second time, this time there should be no exception, because we now provide the correct password
        authenticator.setPassword(user1.getPassword());
        consumer.poll();
    } finally {
        consumer.close();
    }
}

